 }

 .ui-card__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 10px;
 }

 .ui-card__id {
   font-size: 0.72rem;
   font-weight: 700;
   letter-spacing: 0.09em;
   text-transform: uppercase;
