 .ui-jobmap__body {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-jobmap__name {
   font-size: 0.88rem;
 }

 .ui-jobmap__stage {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-jobmap__note {
   font-size: 0.78rem;
   color: var(--studio-muted);
 }

 /* Decision record */
 .ui-fields {
   margin: 0;
   display: flex;
   flex-direction: column;
   gap: 10px;
 }

 .ui-field {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-field dt {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-field dd {
   margin: 0;
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 @media (max-width: 640px) {
